css:
:root{--paper:#fbfaf7;--paper2:#f1ede4;--ink:#29251f;--muted:#6e655a;--accent:#9a5b3a;--rule:#ddd5c6;--serif:'Noto Serif KR',var(--page-serif),'Nanum Myeongjo',serif}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--serif);font-size:1rem;line-height:1.85;word-break:keep-all;overflow-wrap:break-word;-webkit-font-smoothing:antialiased}
.fo-wrap{max-width:1080px;margin:0 auto;padding:0 clamp(1.25rem,6vw,4rem)}
.fo-sec{padding:clamp(4.5rem,11vw,9rem) 0 0}
.fo-sec:last-of-type{padding-bottom:clamp(4rem,9vw,7rem)}
h1,h2,h3,p,dl,dd,ul,ol,figure{margin:0}
h1{font-weight:800;font-size:clamp(2.4rem,8.4vw,4.5rem);line-height:1.18;letter-spacing:-.035em}
h2{font-weight:800;font-size:clamp(1.6rem,4.4vw,2.25rem);line-height:1.3;letter-spacing:-.025em;max-width:20em}
h3{font-weight:700;font-size:1.125rem;line-height:1.5}
p{max-width:34em}
a{color:var(--accent);text-underline-offset:.25em}
:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
.fo-muted{color:var(--muted)}
.fo-top{padding-top:clamp(2rem,5vw,3.5rem);display:flex;justify-content:space-between;gap:1rem;flex-wrap:wrap;border-bottom:1px solid var(--rule);padding-bottom:1.25rem;font-size:.95rem}
.fo-top b{font-weight:800;font-size:1.125rem;letter-spacing:.02em}
.fo-hero{padding-top:clamp(3.5rem,9vw,7rem)}
.fo-lede{margin-top:2rem;font-size:1.125rem;line-height:1.9}
.fo-timeline{margin-top:clamp(3rem,7vw,5rem);display:grid;gap:1.1rem}
.fo-tl-row{display:grid;grid-template-columns:5.5rem 1fr;gap:1rem;align-items:center}
.fo-tl-row span.fo-tl-k{font-size:.95rem;color:var(--muted)}
.fo-track{display:block;position:relative;height:3.25rem;border-left:2px solid var(--ink)}
.fo-bar{display:flex;align-items:center;height:100%;padding-left:1rem;font-weight:800;font-size:1.5rem;letter-spacing:-.02em;transform-origin:left center;white-space:nowrap}
.fo-bar.is-before{width:100%;background:var(--paper2);color:var(--ink)}
.fo-bar.is-after{width:50%;background:var(--accent);color:var(--paper);animation:fo-draw 1.4s cubic-bezier(.2,.7,.2,1) .5s both}
@keyframes fo-draw{from{transform:scaleX(.01);opacity:.4}to{transform:scaleX(1);opacity:1}}
.fo-tl-note{margin-top:.25rem;font-size:.9rem;color:var(--muted);padding-left:6.5rem}
.fo-hero-nums{margin-top:clamp(3rem,6vw,4.5rem);display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid var(--ink)}
.fo-hero-nums div{padding:1.25rem 1.25rem 0 0}
.fo-hero-nums div+div{padding-left:1.25rem;border-left:1px solid var(--rule)}
.fo-hero-nums dt{font-size:.92rem;color:var(--muted);line-height:1.5}
.fo-hero-nums dd{margin-top:.4rem;font-weight:800;font-size:1.5rem;letter-spacing:-.02em;line-height:1.3}
.fo-hero-nums dd i{font-style:normal;color:var(--accent)}
.fo-body{margin-top:2rem;display:grid;gap:1.25rem}
.fo-metrics{margin-top:clamp(2.5rem,6vw,4rem);display:grid;gap:0}
.fo-metric{display:grid;grid-template-columns:minmax(10rem,15rem) 1fr;gap:1rem 2rem;padding:1.6rem 0;border-top:1px solid var(--rule);align-items:center}
.fo-metric:last-child{border-bottom:1px solid var(--rule)}
.fo-metric h3{font-size:1rem;font-weight:600;line-height:1.55}
.fo-metric h3 small{display:block;font-weight:400;color:var(--muted);font-size:.88rem}
.fo-mbars{display:grid;gap:.5rem}
.fo-mb{display:block;height:1.75rem;position:relative}
.fo-mb em{position:absolute;left:0;top:0;bottom:0;display:block}
.fo-mb.b em{background:var(--paper2);border-right:2px solid var(--rule)}
.fo-mb.a em{background:var(--accent)}
.fo-mb span{position:absolute;left:.7rem;top:0;line-height:1.75rem;font-size:.92rem;font-weight:700;white-space:nowrap}
.fo-mb.a span{color:var(--paper)}
.fo-case{margin-top:2.5rem;display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);gap:clamp(2rem,6vw,5rem);align-items:start}
.fo-when{margin-top:.9rem;color:var(--accent);font-size:.98rem;font-weight:600}
.fo-side{border-left:2px solid var(--accent);padding-left:1.5rem;display:grid;gap:1.4rem}
.fo-side dt{font-weight:800;font-size:.98rem}
.fo-side dd{margin-top:.2rem;font-size:.97rem;line-height:1.75;color:var(--ink)}
.fo-side dd+dt{margin-top:0}
.fo-pair{margin-top:2.25rem;display:flex;flex-wrap:wrap;gap:2.5rem}
.fo-pair div{display:block}
.fo-pair strong{display:block;font-size:2rem;font-weight:800;letter-spacing:-.025em;line-height:1.3}
.fo-pair span{font-size:.92rem;color:var(--muted)}
.fo-steps{list-style:none;padding:0;margin-top:2.5rem;display:grid;grid-template-columns:repeat(4,1fr);gap:0;counter-reset:s;border-top:1px solid var(--ink)}
.fo-steps li{counter-increment:s;padding:1.25rem 1.25rem 0 0;position:relative;font-size:.97rem;line-height:1.75}
.fo-steps li+li{padding-left:1.25rem;border-left:1px solid var(--rule)}
.fo-steps li::before{content:counter(s);display:block;font-weight:800;font-size:1.5rem;color:var(--accent);line-height:1.2;margin-bottom:.35rem}
.fo-steps b{display:block;font-weight:800;margin-bottom:.25rem;font-size:1.05rem}
.fo-dots{margin-top:3rem;display:flex;gap:2rem;align-items:center;flex-wrap:wrap}
.fo-grid48{display:block;width:288px;height:96px;max-width:100%;background-image:radial-gradient(circle at 12px 12px,var(--accent) 6px,transparent 6.5px);background-size:24px 24px}
.fo-dots p{font-size:.95rem;color:var(--muted);max-width:18em}
.fo-dots p b{display:block;color:var(--ink);font-size:1.5rem;font-weight:800}
.fo-quote{background:var(--paper2);padding:clamp(3rem,8vw,6rem) 0;margin-top:clamp(4.5rem,11vw,9rem)}
.fo-quote .fo-sec{padding:0}
.fo-quote h2{max-width:16em;font-size:clamp(1.75rem,5.4vw,3rem);line-height:1.35}
.fo-quote p{margin-top:1.5rem}
.fo-quote .fo-when{margin-top:2rem}
.fo-tools{margin-top:2.5rem;border-top:1px solid var(--ink)}
.fo-tools div{display:grid;grid-template-columns:minmax(9rem,14rem) 1fr;gap:.5rem 2rem;padding:1.15rem 0;border-bottom:1px solid var(--rule)}
.fo-tools dt{font-weight:800}
.fo-tools dd{max-width:36em}
.fo-two{margin-top:2.5rem;display:grid;grid-template-columns:1.25fr 1fr;gap:clamp(2rem,6vw,5rem)}
.fo-two article:last-child{padding-top:3rem}
.fo-two h3{font-size:1.25rem;margin-bottom:.4rem}
.fo-two p{font-size:.98rem}
.fo-two .fo-when{margin:0 0 .5rem}
.fo-list{list-style:none;padding:0;margin-top:2rem;border-top:1px solid var(--ink)}
.fo-list li{padding:1.1rem 0;border-bottom:1px solid var(--rule);display:grid;grid-template-columns:minmax(8rem,12rem) 1fr;gap:.25rem 2rem}
.fo-list .k{color:var(--accent);font-weight:600;font-size:.95rem}
.fo-list h3{font-size:1.02rem;font-weight:700}
.fo-list p{font-size:.94rem;color:var(--muted);margin-top:.15rem;line-height:1.7}
.fo-career{margin-top:2rem;display:grid;grid-template-columns:minmax(8rem,12rem) 1fr;gap:.5rem 2rem;padding-top:1.4rem;border-top:1px solid var(--ink)}
.fo-career .k{color:var(--accent);font-weight:600}
.fo-career h3{margin-bottom:.35rem}
@media(max-width:760px){
.fo-hero-nums{grid-template-columns:1fr}
.fo-hero-nums div,.fo-hero-nums div+div{padding:1rem 0;border-left:0;border-bottom:1px solid var(--rule)}
.fo-metric,.fo-tools div,.fo-list li,.fo-career{grid-template-columns:1fr}
.fo-case,.fo-two{grid-template-columns:1fr}
.fo-two article:last-child{padding-top:0}
.fo-steps{grid-template-columns:1fr}
.fo-steps li,.fo-steps li+li{padding:1.1rem 0;border-left:0;border-bottom:1px solid var(--rule)}
.fo-tl-row{grid-template-columns:1fr;gap:.35rem}
.fo-tl-note{padding-left:0}
.fo-bar{font-size:1.15rem}
}
@media(prefers-reduced-motion:reduce){.fo-bar.is-after{animation:none}html{scroll-behavior:auto}}
